106:             .getProxy()
107:             .getGroups()
108:             .stream()
109:             .filter(group -> group.getEndpoints() != null)
110:             .forEach(group -> {
111:                 final Set<Endpoint> endpoints = group.getEndpoints();
112:                 if (endpoints instanceof ObservableSet) {
113:                     apiHandlers.put(api, new ArrayList<>());
114:                     ((ObservableSet) endpoints).addListener(new EndpointsListener(api));
115:                 }
116:             });
117: 
118:         // Configure handlers on resolved API endpoints
119:         final List<EndpointRule> healthCheckEndpoints = endpointResolver.resolve(api);
120:         if (!healthCheckEndpoints.isEmpty()) {
121:             log.debug("Health-check for API id[{}] name[{}] is enabled", api.getId(), api.getName());
122:             apiHandlers.put(api, new ArrayList<>());
123:             healthCheckEndpoints.forEach(rule -> addHandler(api, rule));
124:         }
125:     }
126: 
127:     private void stopHealthCheck(Api api) {
128:         removeHandlers(api);
129:     }
130: 
131:     private void addHandler(Api api, EndpointRule rule) {
132:         try {
133:             final HealthCheckContext healthCheckContext = healthCheckContextFactory.create(
134:                 new ApiTemplateVariableProvider(api),
135:                 api.getEnvironmentId()
136:             );
137: 
138:             EndpointRuleHandler runner = rule.createRunner(vertx, rule, healthCheckContext.getTemplateEngine(), environment);
139:             runner.setStatusHandler(statusReporter);
140:             runner.setAlertEventProducer(alertEventProducer);
141:             runner.setNode(node);
142:             EndpointRuleCronHandler cronHandler = new EndpointRuleCronHandler(vertx, rule);
143:             cronHandler.schedule(runner);
144: 
145:             apiHandlers.get(api).add(cronHandler);
146: 
147:             log.debug(
148:                 "Add health-check for endpoint name[{}] target[{}] with cron[{}]",
149:                 rule.endpoint().getName(),
150:                 rule.endpoint().getTarget(),
151:                 rule.schedule()
152:             );
153:         } catch (Exception ex) {
154:             log.error("An error occurs while creating an health-check runner", ex);
155:         }
156:     }
157: 
158:     private void removeHandlers(Api api) {
159:         List<EndpointRuleCronHandler> handlers = apiHandlers.remove(api);
160:         if (handlers != null) {
161:             log.debug("Stop health-check for API id[{}] name[{}]", api.getId(), api.getName());
162:             handlers.forEach(handler -> handler.cancel());
163:         }
164:     }
