166:     private void removeHandler(Api api, Endpoint endpoint) {
167:         List<EndpointRuleCronHandler> cronHandlers = apiHandlers.get(api);
168:         if (cronHandlers != null) {
169:             Optional<EndpointRuleCronHandler> endpointCronHandler = cronHandlers
