177:                     handler.getTimerId(),
178:                     endpoint.getName(),
179:                     endpoint.getType(),
180:                     endpoint.getTarget()
181:                 );
182:                 handler.cancel();
183:                 cronHandlers.remove(handler);
184:             });
185:         }
186:     }
